  .rd-input { flex: 1; padding: 13px 16px; border: 2px solid #e2e8f0; border-radius: 12px; font-size: 16px; font-family: 'Cairo', sans-serif; outline: none; direction: ltr; text-align: right; transition: border 0.2s; }
